package com.oms.order.service;

import org.junit.jupiter.api.*;
import org.springframework.test.util.ReflectionTestUtils;
import java.util.*;
import java.util.concurrent.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static com.oms.order.service.OrderValues.*;

class OrderPlatformShippingServiceTest {
    @Test void mixedPhysicalPackageReportsPurchasedQuantityAndExcludesOmsGift(){
        long order=f.fixture.db.queryForObject("SELECT order_id FROM oms_order_shipment WHERE id=?",Long.class,f.shipment);
        long gift=f.fixture.repository.insert("INSERT INTO oms_order_line(company_code,order_id,platform_oid,sku_sn,goods_name,quantity,payment,reserved_quantity,gift_plan_id) VALUES ('VERIFY',?,'','G','gift',1,0,1,123)",order);
        long shipped=f.fixture.repository.insert("INSERT INTO oms_order_shipment_line(company_code,shipment_id,order_line_id,platform_oid,sku_sn,goods_name,quantity,shipped_quantity,allocation_id,stock_source_id,store_code,batch_id,source_type) VALUES ('VERIFY',?,?,'','G','gift',1,1,999,999,'W1',999,'PUBLIC_EXTRA')",f.shipment,gift);
        f.fixture.db.update("UPDATE oms_order_shipment SET quantity=quantity+1 WHERE id=?",f.shipment);f.fixture.db.update("UPDATE oms_order_shipment_outbound SET quantity=quantity+1 WHERE shipment_id=? AND state='COMPLETED'",f.shipment);
        new OrderShipmentOutboundRecords(f.fixture.repository).packageRecord("VERIFY",f.fixture.service.detail("VERIFY",f.shipment),null,f.row("package_code","SIMPKG_MIXED","express_code","TEST-SF-MIXED","carrier_code","SF","carrier_name","顺丰","lines",Arrays.asList(f.row("id",line,"quantity",4),f.row("id",shipped,"quantity",1))),"VIRTUAL","PLATFORM_PACKAGE_MIXED","tester");
        service.enqueue("VERIFY",f.shipment,"tester");Map<String,Object> task=f.fixture.db.queryForMap("SELECT quantity,payload_json FROM oms_order_platform_shipping_task");assertEquals(4,number(task,"quantity"));Map<String,Object> payload=GiftRules.object(task.get("payload_json"));assertEquals(1,number(payload,"oms_gift_quantity"));assertFalse(((Map<?,?>)payload.get("goods")).containsKey(""));assertEquals(1,((List<?>)payload.get("lines")).size());
    }
    OrderVirtualOutboundServiceTest f=new OrderVirtualOutboundServiceTest();OrderPlatformShippingService service;OrderPlatformShippingGateway gateway;long line;
    @BeforeAll static void start(){OrderVirtualOutboundServiceTest.start();}
    @BeforeEach void seed(){f.seed();for(String table:Arrays.asList("oms_order_platform_shipping_log","oms_order_platform_shipping_task","oms_order_platform_shipping_config","oms_order_platform_shipping_sim_receipt","oms_order_issue_event","oms_order_issue"))f.fixture.db.update("DELETE FROM "+table);f.submit(1,4);f.service.process("VERIFY",f.shipment);line=f.fixture.db.queryForObject("SELECT id FROM oms_order_shipment_line",Long.class);service=new OrderPlatformShippingService(f.fixture.repository);gateway=new OrderPlatformShippingGateway(f.fixture.repository);ReflectionTestUtils.setField(service,"gateway",gateway);OrderPlatformInteractionRecorder recorder=mock(OrderPlatformInteractionRecorder.class);when(recorder.record(anyMap(),anyBoolean(),any())).thenAnswer(a->((java.util.function.Supplier<?>)a.getArgument(2)).get());ReflectionTestUtils.setField(gateway,"interactions",recorder);enable();}
    void enable(){service.saveConfiguration("VERIFY",1,f.row("mode","SIMULATION","control_version",number(service.configuration("VERIFY",1),"control_version"),"carrier_mapping",f.row("SF","SF")),"tester");}
    void off(){service.saveConfiguration("VERIFY",1,f.row("mode","OFF","control_version",number(service.configuration("VERIFY",1),"control_version"),"carrier_mapping",f.row()),"tester");}
    long parcel(long shipment,long line,int qty,String suffix){return new OrderShipmentOutboundRecords(f.fixture.repository).packageRecord("VERIFY",f.fixture.service.detail("VERIFY",shipment),null,f.row("package_code","SIMPKG_"+suffix,"express_code","TEST-SF-"+suffix,"carrier_code","SF","carrier_name","顺丰","lines",Arrays.asList(f.row("id",line,"quantity",qty))),"VIRTUAL","PLATFORM_PACKAGE_"+suffix,"tester");}
    long task(){return f.fixture.db.queryForObject("SELECT id FROM oms_order_platform_shipping_task ORDER BY id DESC LIMIT 1",Long.class);}
    String state(){return f.fixture.db.queryForObject("SELECT state FROM oms_order_platform_shipping_task ORDER BY id DESC LIMIT 1",String.class);}
    void due(){f.fixture.db.update("UPDATE oms_order_platform_shipping_task SET next_attempt=NOW()");}
    int count(String table){return f.fixture.db.queryForObject("SELECT COUNT(*) FROM "+table,Integer.class);}
    @Test void sameChildOrderInMultipleParcelsRetainsExactQuantityAndIsIdempotent(){
        parcel(f.shipment,line,2,"ONE");parcel(f.shipment,line,2,"TWO");String before=encode(f.document().get("outbound_records"));service.enqueue("VERIFY",f.shipment,"tester");service.enqueue("VERIFY",f.shipment,"tester");assertEquals(2,count("oms_order_platform_shipping_task"));
        for(long id:f.fixture.db.queryForList("SELECT id FROM oms_order_platform_shipping_task",Long.class)){service.process("VERIFY",id);service.process("VERIFY",id);}
        assertEquals(2,count("oms_order_platform_shipping_sim_receipt"));assertEquals(2,f.fixture.db.queryForObject("SELECT COUNT(*) FROM oms_order_platform_shipping_task WHERE state='SUCCESS' AND attempts=1",Integer.class));assertEquals(4,number(f.document(),"platform_shipping_success_quantity"));assertEquals("PART_SHIPPED",f.document().get("status"));assertEquals(4,number(f.document(),"shipped_quantity"));assertEquals(before,encode(f.document().get("outbound_records")));
        Map<String,Object> snap=(Map<String,Object>)((List<Map<String,Object>>)service.report("VERIFY",f.shipment).get("tasks")).get(0).get("snapshot");assertEquals("12345",snap.get("platform_tid"));assertEquals(2,number((Map<String,Object>)snap.get("goods"),"123450"));assertEquals("PACKAGE_INCREMENT",snap.get("notification_type"));
    }
    @Test void lostReplyIsResolvedByQueryEvenIfShopDisabledWithoutResending(){
        parcel(f.shipment,line,4,"LOST");service.enqueue("VERIFY",f.shipment,"tester");OrderPlatformShippingGateway spy=spy(gateway);doAnswer(i->{gateway.send(i.getArgument(0));throw new IllegalStateException("lost response");}).when(spy).send(anyMap());ReflectionTestUtils.setField(service,"gateway",spy);
        service.process("VERIFY",task());assertEquals("UNKNOWN",state());assertEquals(1,count("oms_order_platform_shipping_sim_receipt"));assertEquals(1,count("oms_order_issue"));assertThrows(IllegalArgumentException.class,()->service.action("VERIFY",f.shipment,task(),"RETRY","tester"));off();due();service.process("VERIFY",task());assertEquals("SUCCESS",state());verify(spy,times(1)).send(anyMap());verify(spy,times(1)).query(anyMap());assertEquals("RESOLVED",f.fixture.db.queryForObject("SELECT state FROM oms_order_issue",String.class));
    }
    @Test void knownTransientFailureAutoRetriesThreeTimesThenManualRetryUsesOriginalSnapshot(){
        parcel(f.shipment,line,4,"RETRY");service.enqueue("VERIFY",f.shipment,"tester");OrderPlatformShippingGateway mock=mock(OrderPlatformShippingGateway.class);when(mock.send(anyMap())).thenReturn(OrderPlatformShippingGateway.result("RETRYABLE","模拟服务暂忙", ""));ReflectionTestUtils.setField(service,"gateway",mock);
        for(int n=0;n<3;n++){due();service.process("VERIFY",task());}assertEquals("FAILED",state());assertEquals(3,f.fixture.db.queryForObject("SELECT attempts FROM oms_order_platform_shipping_task",Integer.class));String payload=f.fixture.db.queryForObject("SELECT payload_json FROM oms_order_platform_shipping_task",String.class);String request=f.fixture.db.queryForObject("SELECT request_id FROM oms_order_platform_shipping_task",String.class);
        service.action("VERIFY",f.shipment,task(),"RETRY","tester");assertEquals("OPEN",f.fixture.db.queryForObject("SELECT state FROM oms_order_issue",String.class));ReflectionTestUtils.setField(service,"gateway",gateway);service.process("VERIFY",task());assertEquals("SUCCESS",state());assertEquals(4,f.fixture.db.queryForObject("SELECT attempts FROM oms_order_platform_shipping_task",Integer.class));assertEquals(payload,f.fixture.db.queryForObject("SELECT payload_json FROM oms_order_platform_shipping_task",String.class));assertEquals(request,f.fixture.db.queryForObject("SELECT request_id FROM oms_order_platform_shipping_task",String.class));
    }
    @Test void unknownWithoutReceiptNeverResendsAndExpiredProcessingIsQueryOnly(){
        parcel(f.shipment,line,4,"UNKNOWN");service.enqueue("VERIFY",f.shipment,"tester");OrderPlatformShippingGateway spy=spy(gateway);ReflectionTestUtils.setField(service,"gateway",spy);f.fixture.db.update("UPDATE oms_order_platform_shipping_task SET state='PROCESSING',lease_until=DATE_SUB(NOW(),INTERVAL 5 SECOND),lease_token='old'");service.process("VERIFY",task());assertEquals("UNKNOWN",state());due();service.process("VERIFY",task());verify(spy,never()).send(anyMap());verify(spy,times(2)).query(anyMap());assertEquals(0,count("oms_order_platform_shipping_sim_receipt"));
    }
    @Test void incompletePostingRealWaybillMissingMappingTenantAndSnapshotMismatchAreRejected(){
        parcel(f.shipment,line,2,"VALID");parcel(f.shipment,line,2,"BAD");f.fixture.db.update("UPDATE oms_order_shipment_package SET express_code='REAL-SF-1' WHERE express_code='TEST-SF-BAD'");assertThrows(IllegalArgumentException.class,()->service.enqueue("VERIFY",f.shipment,"tester"));assertEquals(0,count("oms_order_platform_shipping_task"));assertThrows(IllegalArgumentException.class,()->service.report("OTHER",f.shipment));assertThrows(IllegalArgumentException.class,()->service.saveConfiguration("VERIFY",1,f.row("mode","PRODUCTION","control_version",1,"carrier_mapping",f.row()),"tester"));
        f.fixture.db.update("UPDATE oms_order_shipment_package SET express_code='TEST-SF-BAD' WHERE express_code='REAL-SF-1'");service.saveConfiguration("VERIFY",1,f.row("mode","SIMULATION","control_version",1,"carrier_mapping",f.row("JD","JD")),"tester");assertThrows(IllegalArgumentException.class,()->service.enqueue("VERIFY",f.shipment,"tester"));enable();f.fixture.db.update("UPDATE oms_order_shipment_package_line SET platform_oid='foreign' WHERE package_id=(SELECT id FROM oms_order_shipment_package WHERE express_code='TEST-SF-BAD')");assertThrows(IllegalArgumentException.class,()->service.enqueue("VERIFY",f.shipment,"tester"));assertEquals(0,count("oms_order_platform_shipping_task"));
    }
    @Test void disabledShopPausesNewSendAndAutomaticScanDoesNotBackfillHistory(){
        parcel(f.shipment,line,4,"OLD");f.fixture.db.update("UPDATE oms_order_shipment_package SET create_time='2000-01-01 00:00:00'");service.pollCompany("VERIFY");assertEquals(0,count("oms_order_platform_shipping_task"));service.enqueue("VERIFY",f.shipment,"tester");off();service.process("VERIFY",task());assertEquals("PENDING",state());assertEquals(0,count("oms_order_platform_shipping_sim_receipt"));enable();service.process("VERIFY",task());assertEquals("SUCCESS",state());
    }
    @Test void automaticNewParcelOnExistingShipmentDoesNotEnrollItsOldParcel(){
        long old=parcel(f.shipment,line,2,"HISTORICAL");f.fixture.db.update("UPDATE oms_order_shipment_package SET create_time='2000-01-01 00:00:00' WHERE id=?",old);long fresh=parcel(f.shipment,line,2,"NEW");service.pollCompany("VERIFY");assertEquals(1,count("oms_order_platform_shipping_task"));assertEquals(fresh,f.fixture.db.queryForObject("SELECT package_id FROM oms_order_platform_shipping_task",Long.class));assertEquals(2,number(f.document(),"platform_shipping_success_quantity"));assertEquals("PART_SUCCESS",f.document().get("platform_shipping_state"));
    }
    @Test void multiplePhysicalWarehousesShareOneTidButKeepIndependentParcelTasks(){
        f.fixture.db.update("DELETE FROM oms_order_shipment_package_line");f.fixture.db.update("DELETE FROM oms_order_shipment_package");f.fixture.db.update("DELETE FROM oms_order_shipment_outbound");f.fixture.db.update("DELETE FROM oms_order_shipment_line");f.fixture.db.update("DELETE FROM oms_order_shipment");f.fixture.db.update("UPDATE oms_order SET status='WAIT_ALLOCATION',control_version=0");when(f.catalog.warehouses("VERIFY")).thenReturn(Arrays.asList(f.row("wms_simulation_code","V1","owner_code","O1","real_store_code","R1","outbound_mode",2),f.row("wms_simulation_code","V2","owner_code","O1","real_store_code","R2","outbound_mode",2)));f.fixture.mirror(Arrays.asList(f.fixture.receipt(1,4,"V1","R1"),f.fixture.receipt(2,6,"V2","R2")));List<Map<String,Object>> ships=f.fixture.generate(0);assertEquals(2,ships.size());
        f.fixture.db.update("UPDATE oms_order_shipment SET status='SHIPPED',carrier_code='SF'");f.fixture.db.update("UPDATE oms_order_shipment_line SET shipped_quantity=quantity");
        for(Map<String,Object> ship:ships){long id=number(ship,"id"),qty=number(ship,"quantity");Map<String,Object> out=f.row("request_id","OUT_"+id,"quantity",qty,"lines",Collections.emptyList());new OrderShipmentOutboundRecords(f.fixture.repository).virtual("VERIFY",ship,out,"tester");long l=f.fixture.db.queryForObject("SELECT id FROM oms_order_shipment_line WHERE shipment_id=?",Long.class,id);parcel(id,l,(int)qty,"WARE_"+id);service.enqueue("VERIFY",id,"tester");}
        for(long id:f.fixture.db.queryForList("SELECT id FROM oms_order_platform_shipping_task",Long.class))service.process("VERIFY",id);assertEquals(2,count("oms_order_platform_shipping_sim_receipt"));assertEquals(10,f.fixture.db.queryForObject("SELECT SUM(quantity) FROM oms_order_platform_shipping_task WHERE state='SUCCESS'",Integer.class));
    }
    @Test void concurrentWorkerClaimsSendExactlyOnce() throws Exception {
        parcel(f.shipment,line,4,"RACE");service.enqueue("VERIFY",f.shipment,"tester");long id=task();OrderPlatformShippingGateway spy=spy(gateway);CountDownLatch sending=new CountDownLatch(1),release=new CountDownLatch(1);doAnswer(i->{sending.countDown();assertTrue(release.await(10,TimeUnit.SECONDS));return gateway.send(i.getArgument(0));}).when(spy).send(anyMap());ReflectionTestUtils.setField(service,"gateway",spy);ExecutorService pool=Executors.newFixedThreadPool(2);
        try{Future<?> a=pool.submit(()->service.process("VERIFY",id));assertTrue(sending.await(10,TimeUnit.SECONDS));pool.submit(()->service.process("VERIFY",id)).get(10,TimeUnit.SECONDS);release.countDown();a.get(10,TimeUnit.SECONDS);}finally{release.countDown();pool.shutdownNow();}verify(spy,times(1)).send(anyMap());assertEquals("SUCCESS",state());assertEquals(1,count("oms_order_platform_shipping_sim_receipt"));
    }
}
